"""Validate the pinned provider's changed Python protocol before SDK startup."""
import argparse,base64,hashlib,json,os,subprocess,sys
from pathlib import Path
TESTS={'test_parallel_reads.py': {'sha256': '01572a87b8fbbabc999c0c40b2e25d48bd558600d94e1df646ee955121e8213e', 'data': ''}, 'test_lazy_cache.py': {'sha256': 'd23ede2efe49dc6abd8d77fb237e40b0237f911538d97b179a0512b762ac9538', 'data': ''}, 'test_lazy_lifecycle.py': {'sha256': '2cb437e2657339b09c682a3a66dcb8949731b84b259f7a14349ed788853f186f', 'data': ''}, 'test_control_lifecycle.py': {'sha256': 'fbd84c6b3bd9b48f7add6fe331e13a2d062b99f4c72bebd2b9cf1fd957b47285', 'data': ''}, 'test_residency.py': {'sha256': 'd7de3af5569ab383bed47e795e560ec4d7eb724c99bace346a63a40fa22a73d0', 'data': ''}}
SOURCE_PINS={'bindings.py': '751c47bfdca6170279d2b07a056e15fff880c642e0028d9e58fc718eaef7cb02', 'contract.py': '0c47efda619977b708fdb88f9195e49ea7b9bc45c9ec28de75e9173d3cfe8be9', 'io.py': '0a42d175d199e676819c02a1a8594af7e2946c0563f4e966ef902ce2e3f20956', 'lazy.py': '78936996bbf9b3a61950208da9e03c96fa1fa41517f7add66efb2c942a3c25ee', 'lazy_service.py': 'f4e87898430d6b51640cce171e6be672fe2530a03d72c7580e72f89285a7f0e3', 'raw.py': 'e8a95882197eec441a49ffb7cea11ab5b8d939c14c181f21cea1ae3a547684e7', 'sdk.py': 'd7fe2d35aeedb2423cbed387c284a71b5336fe24a221b91aa9e7d30cac0189f3', 'service.py': '12ac070947e9a5e07b1aa81feb72f2c3256daa7daf3422f6bde3c645922dfbdc', 'stored.py': 'dd2c001b2e87fe07e6be9db287221e0686845e90b8a14b11039baa7b3cd762a8', '__init__.py': 'd2874d88f7d86870ee8386ef2f7bad5e451b4fce5beef6c7b488998b0250665b', '__main__.py': '1b29b9dcdcba2813c13dd0b616e5942c24aba97be245869ee145a04f47e5d9d9'}
PROVIDER_COMMIT='2f1550f826d858e9a230cd28a8386c2028ab225b'
def need(ok,message):
    if not ok:raise RuntimeError(message)
def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--source',type=Path,required=True);p.add_argument('--run',action='store_true');a=p.parse_args()
    if not a.run:print('PROVIDER_TEST_PLAN_NO_SDK');return
    need(sys.platform=='linux' and os.getuid()==os.geteuid()==1204,'Use ordinary Linux experiment user')
    source=a.source
    need(source.is_absolute() and source.resolve(strict=True)==source and source.is_relative_to(Path('/home/jwk/agent/r')),'Unexpected staged provider source')
    need((source/'aenv_ub_provider').is_dir(),'Provider package missing')
    for name,pin in SOURCE_PINS.items():
        path=source/'aenv_ub_provider'/name
        need(Path(name).name==name and path.resolve(strict=True)==path and path.stat().st_uid==1204
             and not path.stat().st_mode&0o022 and path.stat().st_size<=1024**2,
             'Unexpected provider source file')
        need(hashlib.sha256(path.read_bytes()).hexdigest()==pin,'Provider source is not the reviewed version')
    destination=source/'protocol-tests'
    need(not destination.exists() and not destination.is_symlink(),'Previous test directory preserved')
    os.umask(0o077);destination.mkdir(mode=0o700)
    for name,item in TESTS.items():
        need(Path(name).name==name,'Unexpected test path')
        data=base64.b64decode(item['data'],validate=True)
        need(hashlib.sha256(data).hexdigest()==item['sha256'],'Pinned test differs')
        with (destination/name).open('xb') as out:out.write(data)
    report={'providerCoreCommit':PROVIDER_COMMIT,'SDK_called':False,'Guest_created':False,'servicesChanged':False,'phases':[]}
    try:
        for name in ('test_parallel_reads.py','test_lazy_lifecycle.py','test_residency.py'):
            with (destination/(name+'.log')).open('xb') as log:
                result=subprocess.run([sys.executable,'-I','-B','-m','unittest','discover','-s',str(destination),'-p',name],stdout=log,stderr=subprocess.STDOUT,timeout=60)
            report['phases'].append({'name':name,'exitCode':result.returncode})
            need(result.returncode==0,'Pinned provider protocol test failed: '+name)
        report['status']='PROVIDER_PROTOCOL_TESTS_PASSED_NO_SDK'
    except BaseException as error:
        report.update(status='PROVIDER_PROTOCOL_TESTS_STOPPED_NO_SDK',errorType=type(error).__name__)
        raise
    finally:
        with (destination/'return.json').open('x') as out:json.dump(report,out,indent=2)
        print(json.dumps(report,indent=2))
if __name__=='__main__':main()
